-- Zing private messaging schema. Already applied in the Supabase project zing-social-eu.
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(char_length(username) between 3 and 24),display_name text not null default '',created_at timestamptz not null default now());
create table public.conversations (id uuid primary key default gen_random_uuid(),created_by uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table public.conversation_members (conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,joined_at timestamptz not null default now(),primary key(conversation_id,user_id));
create table public.messages (id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,content text not null check(char_length(content) between 1 and 2000),created_at timestamptz not null default now());
create index messages_conversation_created_idx on public.messages(conversation_id,created_at);
create function public.create_zing_profile() returns trigger language plpgsql security definer set search_path='' as $$ declare n text; begin n:=lower(coalesce(new.raw_user_meta_data->>'username',''));if n !~ '^[a-z0-9_]{3,24}$' then n:='zing_'||left(replace(new.id::text,'-',''),12);end if;insert into public.profiles(id,username,display_name) values(new.id,n,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),n)) on conflict(id) do nothing;return new;end;$$;
create trigger on_auth_user_created_zing_profile after insert on auth.users for each row execute procedure public.create_zing_profile();
create function public.is_zing_conversation_member(wanted_conversation uuid,wanted_user uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.conversation_members cm where cm.conversation_id=wanted_conversation and cm.user_id=wanted_user); $$;
create function public.create_zing_direct_conversation(target_user_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare current_user_id uuid:=auth.uid(); new_id uuid; begin if current_user_id is null then raise exception 'You must be signed in';end if;if target_user_id is null or target_user_id=current_user_id or not exists(select 1 from public.profiles where id=target_user_id) then raise exception 'Choose another Zing member';end if;select c.id into new_id from public.conversations c where public.is_zing_conversation_member(c.id,current_user_id) and public.is_zing_conversation_member(c.id,target_user_id) and (select count(*) from public.conversation_members cm where cm.conversation_id=c.id)=2 limit 1;if new_id is not null then return new_id;end if;insert into public.conversations(created_by) values(current_user_id) returning id into new_id;insert into public.conversation_members(conversation_id,user_id) values(new_id,current_user_id),(new_id,target_user_id);return new_id;end;$$;
alter table public.profiles enable row level security;alter table public.conversations enable row level security;alter table public.conversation_members enable row level security;alter table public.messages enable row level security;
grant select on public.profiles,public.conversations,public.conversation_members,public.messages to authenticated;grant update(username,display_name) on public.profiles to authenticated;grant insert(created_by) on public.conversations to authenticated;grant insert(conversation_id,user_id) on public.conversation_members to authenticated;grant insert(conversation_id,sender_id,content) on public.messages to authenticated;
revoke all on function public.create_zing_profile() from public;revoke all on function public.is_zing_conversation_member(uuid,uuid) from public;revoke all on function public.create_zing_direct_conversation(uuid) from public;grant execute on function public.is_zing_conversation_member(uuid,uuid) to authenticated;grant execute on function public.create_zing_direct_conversation(uuid) to authenticated;
create policy "Signed-in members can see profiles" on public.profiles for select to authenticated using(true);
create policy "Members can update their own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "Members can read their conversations" on public.conversations for select to authenticated using(public.is_zing_conversation_member(id,auth.uid()));
create policy "Members can start a conversation" on public.conversations for insert to authenticated with check(created_by=auth.uid());
create policy "Members can read conversation participants" on public.conversation_members for select to authenticated using(public.is_zing_conversation_member(conversation_id,auth.uid()));
create policy "A creator can add a participant" on public.conversation_members for insert to authenticated with check(user_id=auth.uid() or public.is_zing_conversation_member(conversation_id,auth.uid()));
create policy "Members can read conversation messages" on public.messages for select to authenticated using(public.is_zing_conversation_member(conversation_id,auth.uid()));
create policy "Members can send their own messages" on public.messages for insert to authenticated with check(sender_id=auth.uid() and public.is_zing_conversation_member(conversation_id,auth.uid()));
alter publication supabase_realtime add table public.messages;
